-- Copy of the production table layout (columns, identity, primary keys) for local tests on PostgreSQL.
create schema if not exists admin;
create table admin.app_settings ("key" character varying not null, "value" jsonb default '{}'::jsonb not null, "updated_at" timestamp without time zone, primary key ("key"));
create table admin.failed_jobs ("id" bigserial not null, "uuid" character varying not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" timestamp without time zone default CURRENT_TIMESTAMP not null, primary key ("id"));
create table admin.jobs ("id" bigserial not null, "queue" character varying not null, "payload" text not null, "attempts" smallint not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null, primary key ("id"));
create table admin.migrations ("id" serial not null, "migration" character varying not null, "batch" integer not null, primary key ("id"));
create table admin.password_reset_tokens ("email" character varying not null, "token" character varying not null, "created_at" timestamp without time zone, primary key ("email"));
create table admin.sessions ("id" character varying not null, "user_id" bigint, "ip_address" character varying, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
create table admin.activity_logs ("id" bigserial not null, "user_id" bigint, "action" character varying not null, "subject_type" character varying, "subject_label" character varying, "description" character varying, "ip" character varying, "created_at" timestamp without time zone default CURRENT_TIMESTAMP not null, primary key ("id"));
create table admin.cache ("key" character varying not null, "value" text not null, "expiration" integer not null, primary key ("key"));
create table admin.cache_locks ("key" character varying not null, "owner" character varying not null, "expiration" integer not null, primary key ("key"));
create table admin.media ("id" bigserial not null, "disk" character varying default 'public'::character varying not null, "path" character varying not null, "filename" character varying not null, "mime" character varying, "size" bigint default '0'::bigint not null, "width" integer, "height" integer, "alt" character varying, "uploaded_by" bigint, "created_at" timestamp without time zone, "updated_at" timestamp without time zone, "public_url" character varying, primary key ("id"));
create table admin.users ("id" bigserial not null, "name" character varying not null, "email" character varying not null, "email_verified_at" timestamp without time zone, "password" character varying not null, "role" character varying default 'editor'::character varying not null, "avatar" character varying, "last_login_at" timestamp without time zone, "remember_token" character varying, "created_at" timestamp without time zone, "updated_at" timestamp without time zone, "two_factor_secret" text, "two_factor_recovery_codes" text, "two_factor_confirmed_at" timestamp without time zone, primary key ("id"));
create table public.blog_posts ("slug" text not null, "title" text not null, "category" text not null, "published_on" date default CURRENT_DATE not null, "author" text default 'AchiveX Editorial Team'::text not null, "featured" boolean default false not null, "image" text, "excerpt" text not null, "intro_keyword" text not null, "intro_text" text not null, "sections" jsonb default '[]'::jsonb not null, "published" boolean default true not null, "focus_keyword" text, primary key ("slug"));
create table public.case_studies ("slug" text not null, "title" text not null, "client_type" text not null, "industry" text not null, "services" text[] default '{}'::text[] not null, "image" text, "summary" text not null, "overview" text not null, "challenge" jsonb default '[]'::jsonb not null, "solution" jsonb default '[]'::jsonb not null, "results" jsonb default '[]'::jsonb not null, "sort" integer default 0 not null, "published" boolean default true not null, primary key ("slug"));
create table public.contact_submissions ("id" bigint generated ALWAYS as identity not null, "created_at" timestamp with time zone default now() not null, "name" text not null, "email" text not null, "phone" text, "service" text, "message" text not null, "read_at" timestamp with time zone, "starred" boolean default false not null, "notified_at" timestamp with time zone, primary key ("id"));
create table public.hero_stats ("id" bigint generated ALWAYS as identity not null, "value" text not null, "label" text not null, "sort" integer default 0 not null, primary key ("id"));
create table public.job_openings ("id" bigint generated ALWAYS as identity not null, "title" text not null, "team" text, "location" text, "employment_type" text, "description" text, "sort" integer default 0 not null, "published" boolean default true not null, primary key ("id"));
create table public.locations ("id" bigint generated ALWAYS as identity not null, "city" text not null, "country" text not null, "type" text default 'Office'::text not null, "address" text, "phone" text, "email" text, "is_hq" boolean default false not null, "sort" integer default 0 not null, primary key ("id"));
create table public.milestones ("id" bigint generated ALWAYS as identity not null, "year" text not null, "title" text not null, "description" text, "sort" integer default 0 not null, primary key ("id"));
create table public.news_posts ("slug" text not null, "published_on" date default CURRENT_DATE not null, "title" text not null, "summary" text not null, "image" text, "body" jsonb default '[]'::jsonb not null, "published" boolean default true not null, primary key ("slug"));
create table public.not_found_log ("id" bigint generated ALWAYS as identity not null, "created_at" timestamp with time zone default now() not null, "path" text not null, "referrer" text, primary key ("id"));
create table public.page_sections ("id" bigint generated ALWAYS as identity not null, "page" text default 'home'::text not null, "key" text not null, "label" text not null, "data" jsonb default '{}'::jsonb not null, "sort" integer default 0 not null, "visible" boolean default true not null, "updated_at" timestamp with time zone default now() not null, "type" text, primary key ("id"));
create table public.page_views ("id" bigint generated ALWAYS as identity not null, "created_at" timestamp with time zone default now() not null, "path" text not null, "referrer" text, "device" text, "visitor" text, primary key ("id"));
create table public.pages ("path" text not null, "kind" text default 'custom'::text not null, "title" text not null, "published" boolean default true not null, "content" jsonb default '{}'::jsonb not null, "created_at" timestamp with time zone default now() not null, "updated_at" timestamp with time zone default now() not null, primary key ("path"));
create table public.redirects ("id" bigint generated ALWAYS as identity not null, "from_path" text not null, "to_path" text not null, "status_code" integer default 301 not null, "hits" integer default 0 not null, "active" boolean default true not null, "created_at" timestamp with time zone default now() not null, primary key ("id"));
create table public.seo_meta ("path" text not null, "title" text, "description" text, "focus_keyword" text, "og_image" text, "canonical" text, "noindex" boolean default false not null, "updated_at" timestamp with time zone default now() not null, primary key ("path"));
create table public.site_settings ("key" text not null, "value" jsonb default '{}'::jsonb not null, "updated_at" timestamp with time zone default now() not null, primary key ("key"));
create table public.team_members ("id" bigint generated ALWAYS as identity not null, "name" text not null, "role" text not null, "photo_url" text, "linkedin_url" text, "sort" integer default 0 not null, "published" boolean default true not null, primary key ("id"));
create table public.whitepaper_requests ("id" bigint generated ALWAYS as identity not null, "created_at" timestamp with time zone default now() not null, "whitepaper_slug" text not null, "name" text not null, "email" text not null, "company" text, "job_title" text, "handled_at" timestamp with time zone, "notified_at" timestamp with time zone, primary key ("id"));
create table public.whitepapers ("slug" text not null, "title" text not null, "type" text default 'Whitepaper'::text not null, "description" text not null, "cover" text, "inside" jsonb default '[]'::jsonb not null, "file_url" text, "sort" integer default 0 not null, "published" boolean default true not null, primary key ("slug"));
alter table public.whitepaper_requests add constraint whitepaper_requests_whitepaper_slug_fkey foreign key (whitepaper_slug) references public.whitepapers(slug) on delete cascade;
alter table admin.activity_logs add constraint activity_logs_user_id_foreign foreign key (user_id) references admin.users(id) on delete set null;
alter table admin.media add constraint media_uploaded_by_foreign foreign key (uploaded_by) references admin.users(id) on delete set null;
